export function roadshowChoiceCopyV63(run,index,resolved){
 if(!isRoadshowV63(run))return resolved;
 const stage=run.activityContext.stage;
 if(stage===0)return {...resolved,result:[
  '你把展示和離線備案測過一輪，水蛇確認接待位置。翅膀剛才沒說清楚的功能先不替他保證；等林老師把測試條件講完，你就能拿出對得上的畫面。傑克從展示桌後端出一杯咖啡，小聲問這裡算不算來賓席。',
  '你把翅膀跳過的適用範圍、屎潘蛇沒回答的使用問題各列一欄。水蛇請台下同事把重複提問放進來，準備讓林老師下一段有條理地說明。傑克抱著咖啡路過，你提醒他水蛇正在看；他把杯子換到另一隻手，表示收到。',
  '玩具鵝舉起「請說人話」，全公司前兩排先笑了。水蛇請牠安靜值班，你則把笑完仍沒答案的問題記下來。傑克把咖啡杯放到牠身後，表示本杯由外部董事代為出席；你把流程表豎高了一點。'
 ][index]};
 if(stage===1){
  const worked=resolved.label==='展示回答了問題'||resolved.label==='問出真正的場景'||resolved.label==='玩具鵝換到真問題';
  return {...resolved,result:(worked?
   '你把追問拉回林老師剛才講清楚的條件，再核對展示、範圍和下一步。水蛇讓該回答的人接回自己的問題，翅膀和屎潘蛇的空泛補充沒有直接變成客戶承諾。':
   '有一題仍缺測試或範圍確認，你照林老師的說法明列限制。水蛇記下負責人，沒有讓翅膀一句「可以啦」或屎潘蛇一段市場故事補成已驗證的答案。')+' 傑克又補了一杯咖啡，轉身時拿資料夾擋住杯身，熟練得像今天真正可重現的展示。'};
 }
 const good=resolved.flags.includes('activity44_roadshow_leads');
 return {...resolved,result:(good?
  '水蛇核對完同意聯絡的名單和待辦，宣布 Roadshow 結束。翅膀與屎潘蛇的演講留下不少問號，林老師的說明讓能做什麼終於有了依據；你把兩種紀錄分開，全公司收好設備回去，後續的人接得到真正的下一步。':
  '水蛇宣布 Roadshow 結束，沒有把尚未確認的問題灌進成交數。翅膀和屎潘蛇的保證還要逐條核對，林老師已講清楚的條件先附在資料裡；全公司散場，你帶回一張能繼續補答的清單。')+(index===2?' 你用流程表替杯蓋擋了一下，傑克端著滿杯咖啡外帶出門。水蛇還在提醒員工不要喝，這杯的出席紀錄已經包含到場、續杯和散場。':' 傑克替滿杯咖啡扣好杯蓋，跟著大家外帶出門。水蛇回頭時，他已經過了門；沒有任何一筆咖啡錢算到你的帳上。')};
}

export function roadshowPlayCopyV63(run,played,success){
 if(!isRoadshowV63(run))return null;
 const summary=`六張現場問題卡，${played.measures.hits} 張接到合適的處理位置。`;
 return {summary,label:success?'台上講完，台下也接得住':'問題已收齊，幾題還得補答',result:summary+(success?
  ' 林老師把方法與限制講清楚，你把展示、待確認承諾和後續聯絡分開。水蛇接回節奏，翅膀的「什麼都能做」和屎潘蛇的市場故事終於沒有把同事全捲進同一張保證書。':
  ' 林老師的說明有條理，六位訪客卻不是每題都被分到合適的位置。水蛇請你先列待補，翅膀和屎潘蛇剛才講不清楚的地方，不能靠台下點頭就算答完。')+' 傑克在你交表時又補滿咖啡，端著杯子混進問答動線；這一輪最穩定的產出，可能在咖啡機旁邊。'};
}
